const assert = require('node:assert/strict');
const fs = require('node:fs');
module.exports = async function checkCityRide(page) {
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.setViewportSize({width:1440,height:1000});
  await page.goto('http://127.0.0.1:8765/');
  await page.waitForFunction(() => window.FILM_LIBRARY?.videos.some(v=>v.id==='cityride'));
  await page.locator('#search').fill('City Ride');
  assert.equal(await page.locator('#video-grid .video-card').count(),1);
  await page.locator('#video-grid [data-open="cityride"]').click();
  assert.equal(await page.locator('#open-original-report').isEnabled(),true);
  assert.match(await page.locator('#detail-preference').innerText(),/我很喜欢这种风格/);
  await page.locator('[data-detail-tab="cases"]').click();
  assert.equal(await page.locator('#detail-panel .detail-case').count(),20);
  await page.locator('[data-detail-tab="prompts"]').click();
  assert.equal(await page.locator('#prompt-variant option').count(),11);
  await page.locator('#detail-close').click();
  await page.goto('http://127.0.0.1:8765/reports/cityride/online-report.html');
  await page.waitForFunction(()=>window.reportReady);
  assert.equal(await page.locator('#shot-list .shot').count(),114);
  assert.equal(await page.locator('.camera-cue').count(),127);
  assert.equal(await page.locator('#broll tbody tr').count(),15);
  assert.equal(await page.locator('#film').getAttribute('src'),null,'media remains unpublished');
  assert.ok(await page.locator('#prompt-text').inputValue() === JSON.parse(fs.readFileSync('reports/cityride/timed-camera-prompts.json','utf8')).timelinePrompt);
  await page.locator('#search').fill('zz-no-such-shot-zz');
  assert.equal(await page.locator('#shot-list .shot').count(),0);
  await page.locator('#clear-filters').click();
  assert.equal(await page.locator('#shot-list .shot').count(),114);
  await page.locator('[data-cast="A"]').first().click();
  assert.ok(await page.locator('#shot-list .shot').count()<114);
  await page.locator('#clear-filters').click();
  await page.locator('.frame-btn').first().click();
  assert.equal(await page.locator('#frame-dialog').isVisible(),true);
  await page.locator('#frame-close').click();
  await page.locator('#prompt-tab-1').click();
  assert.ok((await page.locator('#prompt-text').inputValue()).length>300);
  await page.locator('#prompt-tab-0').click();
  await page.locator('#copy-prompt').click();
  assert.equal(await page.locator('#copy-prompt').getAttribute('data-copy-state'),'success');
  for (const width of [1440,390]) {
    await page.setViewportSize({width,height:1000});
    const metrics=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth-innerWidth,overlap:[...document.querySelectorAll('.camera-cue')].some(c=>{const t=c.querySelector('.cue-time'),h=c.querySelector('h4');return t&&h&&t.getBoundingClientRect().bottom>h.getBoundingClientRect().top+.5})}));
    assert.ok(metrics.overflow<=1,'page overflow at '+width+': '+metrics.overflow);
    assert.equal(metrics.overlap,false,'time/title overlap at '+width);
  }
  assert.deepEqual(errors,[]);
  console.log('PASS: City Ride entry, 20 cases, 114 shots, 127 windows, B-roll, prompts, filters and responsive text report');
};
